class Solution { fun punishmentNumber(n:Int):Int{fun canSplit(digits:String,index:Int,sum:Int,target:Int):Boolean{if(index==digits.length)return sum==target;var number=0;for(end in index until digits.length){number=number*10+(digits[end]-'0');if(sum+number>target)break;if(canSplit(digits,end+1,sum+number,target))return true};return false};var answer=0;for(value in 1..n){val square=value*value;if(canSplit(square.toString(),0,0,value))answer+=square};return answer} }
